<script lang="ts">
 import { goto } from '$app/navigation'; import PageHeader from '$lib/components/PageHeader.svelte'; import { changePassword } from '$lib/api/auth'; import { session } from '$lib/features/auth/session.svelte'; let currentPassword=$state(''),newPassword=$state(''),confirmPassword=$state(''),saving=$state(false),message=$state(''),errorMessage=$state('');
 async function submit(event:SubmitEvent){event.preventDefault();errorMessage='';message='';if(newPassword!==confirmPassword){errorMessage='两次输入的新密码不一致';return}if(newPassword.length<8){errorMessage='新密码至少需要 8 个字符';return}saving=true;try{await changePassword(currentPassword,newPassword);message='密码修改成功，正在返回登录页…';session.clear();setTimeout(()=>goto('/login'),600)}catch(e){errorMessage=e instanceof Error?e.message:'密码修改失败'}finally{saving=false}}
</script>
<PageHeader title="账号安全" eyebrow="Account" description="修改本地账号密码。修改成功后当前会话会失效，需要重新登录。" /><section class="workspace-card"><form class="password-form" onsubmit={submit}><label>当前密码<input bind:value={currentPassword} type="password" autocomplete="current-password" /></label><label>新密码<input bind:value={newPassword} type="password" autocomplete="new-password" /></label><label>确认新密码<input bind:value={confirmPassword} type="password" autocomplete="new-password" /></label>{#if errorMessage}<p class="error-message">{errorMessage}</p>{/if}{#if message}<p class="success-message">{message}</p>{/if}<button class="primary-button" disabled={saving}>{saving?'保存中…':'修改密码'}</button></form></section><style>.password-form{display:grid;gap:14px;max-width:460px}.password-form label{display:grid;gap:6px;font-weight:700}.error-message{color:var(--color-danger)}.success-message{color:var(--color-success)}</style>
